    ARRAY['dinamica', 'integracion', 'afectividad', 'confianza', 'autoestima'],
    $json${"unidades": ["manada", "compañía", "tropa", "avanzada"], "duracion": "15 minutos", "cantidad": "12 participantes", "lugares": ["Interior", "sala"], "materiales": ["Sin Materiales"], "areas": ["Afectividad", "Carácter", "Creatividad"], "objetivos": ["Facilitar el conocimiento entre los pares", "Fomentar un entorno de confianza", "Favorecer la comunicación en el grupo", "Crear un clima de pertenencia"], "justificacion_areas": "El Lavado de Autos estimula la afectividad al brindar un espacio seguro para dar y recibir muestras sinceras de afecto fraterno. Fortalece el carácter al afirmar la autoestima y autoimagen positiva de cada participante, y desarrolla la creatividad expresiva mediante la comunicación gestual y la dinamización del encuentro grupal.", "variaciones": "Lavado de Autos con Música Suave: Se utiliza una melodía relajante de fondo mientras los autos avanzan, permitiendo un ritmo pausado y profundo.\n\nTúnel de Palabras de Aliento: Al pasar el auto, los integrantes de las filas expresan en susurros cualidades positivas del participante (ej: \"eres alegre\", \"buen compañero\", \"valiente\").\n\nLavado de Velocidad Adaptada: Para manadas pequeñas, el túnel se realiza sentado en sillas donde el niño avanza en un carrito imaginario.", "recomendaciones": "Respeto Absoluto y Sensibilidad: La regla de oro es que el contacto físico debe ser siempre suave, cuidadoso y fraternal (palmaditas en la espalda, roce suave en hombros). Jamás se permiten empujones, cosquillas ni juegos rudos.\n\nParticipación Voluntaria: Si un integrante muestra timidez o incomodidad ante el contacto físico, se le permite ser \"operador del túnel\" o caminar acompañado por un dirigente sin forzar su espacio personal.\n\nEvaluación y Cierre Emocional: Dedicar siempre unos minutos al final para que los jóvenes verbalicen sus sensaciones. Esta evaluación es clave para desinhibir al grupo y consolidar la confianza mutua.", "objetivos_educativos": [{"id": "6e25f6ed-277c-41b4-9d0f-322b0a2d4c94", "texto": "Acepto las opiniones de mis compañeros, aunque yo piense distinto.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "Infancia Media", "area": "Afectividad", "unidad": "Manada", "como_se_cumple": "Ofreciendo palmaditas y gestos de cariño respetuoso a mis compañeros de seisena al pasar por el túnel del lavado."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "Infancia Tardía", "area": "Afectividad", "unidad": "Manada", "como_se_cumple": "Participando con alegría y sin vergüenza al brindar y recibir las demostraciones de afecto del grupo."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "11 a 13 años", "area": "Afectividad", "unidad": "Tropa", "como_se_cumple": "Brindando contacto físico fraterno y respetuoso a cada participante de la patrulla."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "13 a 15 años", "area": "Afectividad", "unidad": "Tropa", "como_se_cumple": "Recibiendo con gratitud la acogida positiva de mis compañeros al recorrer la fila."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "11 a 13 años", "area": "Afectividad", "unidad": "Compañía", "como_se_cumple": "Expresando muestras de afecto sinceras y cuidadosas a las integrantes de mi patrulla."}, {"id": "3621f4ae-1316-4b3e-8682-3e3c9ad381a7", "texto": "Mantengo mi opinión cuando estoy convencida que es correcta.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "13 a 15 años", "area": "Afectividad", "unidad": "Compañía", "como_se_cumple": "Disfrutando el reconocimiento y las palabras estimulantes brindadas por mis compañeras."}, {"id": "6c2b5054-70e8-4529-957f-a8abea073918", "texto": "Expreso mis opiniones libremente, sin descalificar a los demás.", "texto_terminal": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "rango_edad": "15 a 17 años", "area": "Afectividad", "unidad": "Avanzada", "como_se_cumple": "Manifestando mis sentimientos y empatía abiertamente para fortalecer el clima de confianza de la comunidad."}, {"id": "041daaea-c4a7-472b-a613-951bd25cfa85", "texto": "Reconozco y acepto mis errores.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "Infancia Media", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Reconociéndome como un integrante valioso de la Manada al ser acogido alegremente por mis pares."}, {"id": "b66418eb-3eee-466e-9836-457b3bb922cc", "texto": "Sé lo que puedo hacer y lo que no puedo hacer.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "Infancia Tardía", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Sintiéndome seguro y querido por la seisena durante la evaluación y cierre de la dinámica."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Afirmando mi autoestima y confianza personal al integrarme en la fila del grupo."}, {"id": "c380e11a-571d-4617-924c-aa933ae30138", "texto": "Soy capaz de criticarme.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Aceptando con madurez y alegría las expresiones de aprecio de los demás participantes."}, {"id": "3a35ddd8-f6dc-4e00-a04d-107a0825bd99", "texto": "Escucho las críticas que me hacen los demás y reflexiono sobre ellas.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Fortaleciendo mi sentido de pertenencia y valoración propia ante la patrulla de guías."}, {"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Valorando las demostraciones de estima como un impulso para mi crecimiento personal."}, {"id": "dea08f50-52d5-4d87-ad7f-b7dbbb2702fc", "texto": "Me acepto tal como soy, sin dejar de mirarme críticamente.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "15 a 17 años", "area": "Carácter", "unidad": "Avanzada", "como_se_cumple": "Consolidando mi autoimagen positiva y seguridad personal en el entorno caminante."}, {"id": "e5eada78-3a2d-467e-8d15-da159b60552f", "texto": "Me gusta dibujar y pintar.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "Infancia Media", "area": "Creatividad", "unidad": "Manada", "como_se_cumple": "Expresando sonrisas y gestos espontáneos durante la recreación del túnel de lavado."}, {"id": "47e7e2d8-12cd-447d-8df4-251e83aa547b", "texto": "Trato de hablar claro y conocer nuevas palabras.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "Infancia Tardía", "area": "Creatividad", "unidad": "Manada", "como_se_cumple": "Comunicando mi estado de ánimo alegre mediante el lenguaje corporal del juego."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "11 a 13 años", "area": "Creatividad", "unidad": "Tropa", "como_se_cumple": "Compartiendo de forma natural y transparente mis emociones al finalizar la rueda de lavado."}, {"id": "f9cea3e0-24f4-43ab-9efb-1a4541a29943", "texto": "Ayudo a preparar materiales para las representaciones artísticas.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "13 a 15 años", "area": "Creatividad", "unidad": "Tropa", "como_se_cumple": "Dinamizando la actividad con entusiasmo para que todos se sientan acogidos."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "11 a 13 años", "area": "Creatividad", "unidad": "Compañía", "como_se_cumple": "Fomentando un canal de comunicación afectuoso entre las integrantes de la patrulla."}, {"id": "beb4b3e4-fe1c-4f06-af34-2c7f88202eb7", "texto": "Me gusta cantar y conozco muchas canciones.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "13 a 15 años", "area": "Creatividad", "unidad": "Compañía", "como_se_cumple": "Aportando calidez y empatía para desinhibir y motivar a las compañeras."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "texto_terminal": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "rango_edad": "15 a 17 años", "area": "Creatividad", "unidad": "Avanzada", "como_se_cumple": "Generando un clima de distensión y encuentro auténtico al inicio de las sesiones de la comunidad."}]}$json$::jsonb
